CREATE TABLE app_user (id VARCHAR(36) PRIMARY KEY, external_id VARCHAR(160) NOT NULL UNIQUE, nickname VARCHAR(80) NOT NULL, role VARCHAR(10) NOT NULL CHECK(role IN ('USER','ADMIN')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_session (token_hash CHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX auth_session_expiry_idx ON auth_session(expires_at);
CREATE TABLE activity (id VARCHAR(36) PRIMARY KEY, title VARCHAR(120) NOT NULL, category VARCHAR(15) NOT NULL CHECK(category IN ('WEEKLY','DOMESTIC','HOLIDAY','LEISURE')), cover_url VARCHAR(2048) NOT NULL, gallery_urls TEXT NOT NULL DEFAULT '[]', summary VARCHAR(300) NOT NULL, description TEXT NOT NULL, location VARCHAR(200) NOT NULL, meeting_point VARCHAR(200) NOT NULL, start_at TIMESTAMPTZ NOT NULL, end_at TIMESTAMPTZ NOT NULL, registration_deadline TIMESTAMPTZ NOT NULL, capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 10000), registered_count INTEGER NOT NULL DEFAULT 0 CHECK(registered_count >= 0 AND registered_count <= capacity), status VARCHAR(12) NOT NULL CHECK(status IN ('DRAFT','PUBLISHED','CANCELLED')), price_cents INTEGER NOT NULL DEFAULT 0 CHECK(price_cents=0), currency CHAR(3) NOT NULL DEFAULT 'CNY', version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(end_at>start_at), CHECK(registration_deadline<=start_at));
CREATE INDEX activity_feed_idx ON activity(status,start_at,id);
CREATE TABLE registration (id VARCHAR(36) PRIMARY KEY, activity_id VARCHAR(36) NOT NULL REFERENCES activity(id), user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), participant_name VARCHAR(80) NOT NULL, phone VARCHAR(30) NOT NULL, status VARCHAR(12) NOT NULL CHECK(status IN ('CONFIRMED','CANCELLED')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(activity_id,user_id));
CREATE INDEX registration_user_idx ON registration(user_id,created_at);
CREATE TABLE audit_event (id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36) NOT NULL, entity_id VARCHAR(36) NOT NULL, action VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
